"""Reference selector for Yorika's data-only persona pack.

Caller supplies a category and truthful context. This module is not a model,
an intent classifier, an HTTP service, or an automatically installed feature.
Uses the existing backend.storage.Store records table. Selection is atomic.
"""
import hashlib
import json
import re
import unicodedata
from datetime import datetime, timezone
from pathlib import Path


def canonical(text):
    text = unicodedata.normalize('NFKC', text).casefold().replace('ё', 'е')
    text = re.sub(r'\b(?:мой\s+)?(?:(?:любимый|дорогой|родной)\s+)?(?:хозяин|господин)\b', '', text)
    return ' '.join(re.findall(r'[a-zа-я0-9]+', text))


def fingerprint(text):
    return hashlib.sha256(canonical(text).encode('utf-8')).hexdigest()


class PersonaBank:
    namespace = 'persona_rotation'
    record_id = 'yorika.soul.ru.history.v1'

    def __init__(self, pack_path, store):
        self.store = store
        self.pack = json.loads(Path(pack_path).read_text(encoding='utf-8'))
        self.replies = self.pack['replies']
        if self.pack['schema_version'] != '2.0.0':
            raise ValueError('Unsupported persona schema')
        if len(self.replies) != self.pack['total_replies']:
            raise ValueError('Reply count does not match manifest')
        ids = [r['id'] for r in self.replies]
        hashes = [fingerprint(r['text']) for r in self.replies]
        if len(ids) != len(set(ids)) or len(hashes) != len(set(hashes)):
            raise ValueError('Duplicate persona reply')
        known_categories = {c['id'] for c in self.pack['categories']}
        if any(r['category_id'] not in known_categories for r in self.replies):
            raise ValueError('Unknown persona category')

    @staticmethod
    def eligible(reply, context):
        level = reply['min_romance_level']
        if level and not (context.get('adult_context') is True and context.get('romance_enabled') is True):
            return False
        if level > int(context.get('romance_level', 0)):
            return False
        if reply['scene_required'] and context.get('scene_enabled') is not True:
            return False
        if context.get('distressed') is True and level >= 2:
            return False
        facts = context.get('facts', {})
        return all(facts.get(name) is True for name in reply['required_facts'])

    def choose(self, category_id, context=None, situation=None):
        context = context or {}
        candidates = [r for r in self.replies if r['category_id'] == category_id
                      and (situation is None or r['situation'] == situation)
                      and self.eligible(r, context)]
        if not candidates:
            return None
        db = self.store.connection
        if db.in_transaction:
            raise RuntimeError('Persona selection needs its own transaction')
        db.execute('BEGIN IMMEDIATE')
        try:
            row = db.execute('SELECT payload FROM records WHERE namespace=? AND record_id=?',
                             (self.namespace, self.record_id)).fetchone()
            state = json.loads(row[0]) if row else {
                'seen_ids': [], 'seen_fingerprints': [], 'recent_openings': [],
                'recent_categories': [], 'schema_version': 1,
            }
            used_ids = set(state['seen_ids'])
            used_hashes = set(state['seen_fingerprints'])
            candidates = [r for r in candidates if r['id'] not in used_ids
                          and fingerprint(r['text']) not in used_hashes]
            if not candidates:
                db.rollback()
                return None
            recent = state['recent_openings'][-8:]
            candidates.sort(key=lambda r: (r['opening_family'] in recent, r['ordinal']))
            chosen = candidates[0]
            state['seen_ids'].append(chosen['id'])
            state['seen_fingerprints'].append(fingerprint(chosen['text']))
            state['recent_openings'] = (state['recent_openings'] + [chosen['opening_family']])[-32:]
            state['recent_categories'] = (state['recent_categories'] + [category_id])[-32:]
            encoded = json.dumps(state, ensure_ascii=False, allow_nan=False)
            stamp = datetime.now(timezone.utc).isoformat()
            db.execute('INSERT INTO records(namespace,record_id,payload,updated_at) VALUES(?,?,?,?) '
                       'ON CONFLICT(namespace,record_id) DO UPDATE SET '
                       'payload=excluded.payload,updated_at=excluded.updated_at',
                       (self.namespace, self.record_id, encoded, stamp))
            db.commit()
            return dict(chosen)
        except BaseException:
            db.rollback()
            raise

