"""Read authored dialogue examples. Does not generate or send real messages."""
import json
from pathlib import Path


class DialogueExamples:
    def __init__(self, path):
        self.pack = json.loads(Path(path).read_text(encoding='utf-8'))
        extension = self.pack['dialogue_extension']
        if extension['schema_version'] != '1.0.0':
            raise ValueError('Unknown dialogue schema')
        records = extension['scenarios']
        self.scenarios = {s['id']: s for s in records}
        if len(self.scenarios) != len(records):
            raise ValueError('Duplicate scenario ID')
        for scenario in records:
            nodes = {n['id']: n for n in scenario['nodes']}
            if len(nodes) != len(scenario['nodes']):
                raise ValueError('Duplicate node ID')
            if scenario['entry_node'] not in nodes:
                raise ValueError('Missing entry node')
            for branch in ('main', 'alternative'):
                path = self.route(scenario['id'], branch)
                if [m['role'] for m in path] != ['user','assistant','user','assistant']:
                    raise ValueError('Invalid dialogue role order')
            for node in nodes.values():
                for target in node.get('next', {}).values():
                    if target not in nodes:
                        raise ValueError('Missing branch target')

    def route(self, scenario_id, branch):
        if branch not in ('main', 'alternative'):
            raise ValueError('Branch must be explicitly selected')
        scenario = self.scenarios[scenario_id]
        nodes = {n['id']: n for n in scenario['nodes']}
        current = scenario['entry_node']
        visited = set()
        result = []
        while current is not None:
            if current in visited or current not in nodes:
                raise ValueError('Cycle or missing node')
            visited.add(current)
            node = nodes[current]
            result.append({'node_id':node['id'], 'role':node['role'], 'text':node['text']})
            edges = node.get('next', {})
            current = edges.get(branch) if 'main' in edges else edges.get('default')
        return result

    @staticmethod
    def eligible(scenario, context):
        if scenario['adult_romantic_context_required']:
            if context.get('adult_context') is not True or context.get('romance_enabled') is not True:
                return False
        if scenario['scene_required'] and context.get('scene_enabled') is not True:
            return False
        if context.get('distressed') is True and scenario['mode'] in ('bold_romance','romantic_scene','playful'):
            return False
        return True
